const DB='sims3000-photo-albums',STORE='photos',LIMIT=50;
let database;
function openAlbum(){if(!database)database=new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE,{keyPath:'id',autoIncrement:true});r.onsuccess=()=>resolve(r.result);r.onerror=()=>{database=null;reject(Error('Photo storage is unavailable in this browser.'));};});return database;}
async function transact(mode,action){const db=await openAlbum();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,mode),store=tx.objectStore(STORE);let value,failure;tx.oncomplete=()=>resolve(value);tx.onerror=tx.onabort=()=>reject(failure||Error('Could not save the photo album. Check browser storage space.'));action(store,v=>{value=v;},message=>{failure=Error(message);tx.abort();});});}
export const listSnapshots=()=>transact('readonly',(s,done)=>{const r=s.getAll();r.onsuccess=()=>done(r.result);});
export const addSnapshot=photo=>transact('readwrite',(s,done,fail)=>{const count=s.count();count.onsuccess=()=>{if(count.result>=LIMIT)return fail('This browser has 50 snapshots. Download and delete a photo to make room.');const r=s.add(photo);r.onsuccess=()=>done(r.result);};});
export async function captionSnapshot(id,caption){if(typeof caption!=='string'||caption.length>500)throw Error('Captions can contain up to 500 characters.');return transact('readwrite',(s,done)=>{const r=s.get(id);r.onsuccess=()=>{if(r.result)s.put({...r.result,caption:caption.trim()});done(true);};});}
export const deleteSnapshot=id=>transact('readwrite',(s,done)=>{s.delete(id);done(true);});
export async function captureSnapshot(renderer,city,size,crop=null){if(![640,1024,1600].includes(size))throw Error('Choose a snapshot size.');if(!renderer.assetReady)throw Error('Wait for the city artwork to finish loading.');const hover=renderer.hover,drag=renderer.drag,goalArea=renderer.goalArea;try{renderer.goalArea=null;renderer.hover=null;renderer.drag=null;renderer.draw(renderer.time);}finally{renderer.hover=hover;renderer.drag=drag;renderer.goalArea=goalArea;renderer.dirty=true;}const source=renderer.canvas,image=document.createElement('canvas'),bounds=source.getBoundingClientRect(),sx=crop?crop.x*source.width/bounds.width:0,sy=crop?crop.y*source.height/bounds.height:0,sw=crop?crop.width*source.width/bounds.width:source.width,sh=crop?crop.height*source.height/bounds.height:source.height;image.width=Math.max(1,Math.min(size,Math.round(sw)));image.height=Math.max(1,Math.round((crop?crop.height/crop.width:sh/sw)*image.width));image.getContext('2d').drawImage(source,sx,sy,sw,sh,0,0,image.width,image.height);const metadata={city:city.name,mayor:city.mayorName,month:city.month,startYear:city.startYear,population:city.stats.population,funds:city.funds};const blob=await new Promise(resolve=>image.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not capture this city view.');return{...metadata,caption:'',created:Date.now(),width:image.width,height:image.height,blob};}
export const importSnapshots=photos=>transact('readwrite',(s,done,fail)=>{const count=s.count();count.onsuccess=()=>{if(count.result+photos.length>LIMIT)return fail(`This import needs ${photos.length} free photo slots; only ${LIMIT-count.result} remain. Download and delete photos to make room.`);let lastId;for(const p of photos){const r=s.add(p);r.onsuccess=()=>{lastId=r.result;done(lastId);};}};});
